const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-122.403124, 40.575441);
  const startDate = '2020-08-25';
  const endDate = '2020-08-26'; // End date is exclusive, so it covers 2020-08-25

  // 2. Data Acquisition
  let collection = ee.ImageCollection('NOAA/GEFS/v12/reforecast')
    .filterDate(startDate, endDate)
    .filterBounds(point)
    .select('bc_mass_conc'); // Black carbon mass concentration (kg/m^2)

  // Filter for the 'mean' ensemble member, as GEFS is an ensemble forecast
  collection = collection.filter(ee.Filter.eq('ensemble_member', 'mean'));

  // Check if the collection is empty (C1)
  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`GEFS collection is empty for ${startDate}.`);
    console.log('C1');
    return;
  }
  console.log(`Images found: ${collectionSize}`);

  // Get the image (there should be only one for 'mean' for a single day)
  const image = collection.first();

  // 3. Processing & Calculation
  // Reduce the image to get the black carbon mass concentration at the point.
  // Using a small scale since it's a point query, but GEFS resolution is ~0.25 deg.
  const scale = 27830; // ~0.25 degree resolution at equator
  const bc_mass_conc_kg_m2 = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: scale,
    maxPixels: 1e9,
  }).get('bc_mass_conc').getInfo();

  // Check for C3 (Calculation Failure)
  if (bc_mass_conc_kg_m2 === null || isNaN(bc_mass_conc_kg_m2)) {
    console.log('Calculation for black carbon concentration failed (null/NaN).');
    console.log('C3');
    return;
  }

  // Convert kg/m^2 to mg/m^2 (1 kg = 1,000,000 mg)
  const bc_mass_conc_mg_m2 = bc_mass_conc_kg_m2 * 1e6;

  // No explicit pixel count check needed here as reduceRegion for a point
  // and 'mean' member should always return a value if image exists.
  // If no image exists, C1 already caught it. If the value is null, C3 caught it.

  // 4. Validation & Final Answer
  const threshold = 12; // mg/m^2

  console.log(`Black Carbon Concentration: ${bc_mass_conc_mg_m2.toFixed(2)} mg/m^2`);
  console.log(`Threshold: ${threshold} mg/m^2`);

  if (bc_mass_conc_mg_m2 > threshold) {
    console.log('A'); // Yes, there was more than 12 mg/m^2
  } else {
    console.log('B'); // No, there was not more than 12 mg/m^2
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
